public static void main(String[] args) throws Exception {
    Scanner sc = new Scanner(System.in);
    List<Long> sequence = new ArrayList<Long>();
    int Q = sc.nextInt();
    for (int i = 0; i < Q; i++) {
        int type = sc.nextInt();
        if (type == 1) {
            long x = sc.nextLong();
            sequence.add(x);
        } else if (type == 2) {
            int k = sc.nextInt();
            System.out.println(sequence.get(sequence.size() - k));
        }
    }
}
